# ---------------------------------------------------------------------------
# Suppress harmless stderr noise: macOS TSM / HIToolbox (CapsLock LED,
# NSSoftLinking) and Qt multimedia FFmpeg / PipeWire AAC probe dumps used by
# the in-app demo. Installed from main() after QApplication() — redirecting
# stderr before Qt initialises NSApplication can abort inside
# _RegisterApplication on macOS.
# ---------------------------------------------------------------------------
_STDERR_NOISE_MACOS: tuple = (
    b"TSM AdjustCapsLockLED",
    b"NSSoftLinking",
    b"HIToolbox framework",
)
# Qt multimedia FFmpeg / PipeWire dump AAC probes on Linux (in-app demo).
_STDERR_NOISE_MEDIA: tuple = (
    b"qt.multimedia.ffmpeg",
    b"pw.conf",
    b"can't load config client.conf",
    b"Estimating duration from bitrate",
    b"Input #0, aac, from ",
    b"Stream #0:0: Audio: aac",
)

def _stderr_line_is_noise(line: bytes) -> bool:
    if any(p in line for p in _STDERR_NOISE_MACOS):
        return True
    if any(p in line for p in _STDERR_NOISE_MEDIA):
        return True
    stripped = line.lstrip()
    return stripped.startswith(b"Duration:") and b"bitrate:" in line

def _macos_stderr_line_is_noise(line: bytes) -> bool:
    return _stderr_line_is_noise(line)

def _install_macos_stderr_filter() -> None:
    if os.environ.get("BTF_NO_STDERR_FILTER"):
        return
    try:
        rfd, wfd = os.pipe()
    except OSError:
        return  # Can't create pipe; skip filter
    original_fd = os.dup(2)
    try:
        os.dup2(wfd, 2)
    except OSError:
        os.close(rfd)
        os.close(wfd)
        os.close(original_fd)
        return  # Restore fd 2 unchanged
    os.close(wfd)

    def _relay() -> None:
        leftover = b""
        try:
            with os.fdopen(rfd, "rb", buffering=0) as pipe:
                while True:
                    chunk = pipe.read(256)
                    if not chunk:
                        break
                    leftover += chunk
                    while b"\n" in leftover:
                        line, leftover = leftover.split(b"\n", 1)
                        if not _stderr_line_is_noise(line):
                            try:
                                os.write(original_fd, line + b"\n")
                            except OSError:
                                pass
            if leftover and not _stderr_line_is_noise(leftover):
                try:
                    os.write(original_fd, leftover)
                except OSError:
                    pass
        finally:
            try:
                os.close(original_fd)
            except OSError:
                pass

    t = threading.Thread(target=_relay, daemon=True, name="stderr-filter")
    t.start()

