    key = "dark" if dark else "light"
    palette = STATS_CATEGORY_BADGE_COLORS.get(str(category or "").strip().upper())
    if not palette:
        return STATS_CATEGORY_BADGE_COLORS["DETAIL"][key]
    return palette[key]


