def symptom_section_id(card: Optional[Dict[str, Any]]) -> str:
    if not isinstance(card, dict):
        return "anomalies"
    first = str(card.get("first_section") or "").strip()
    return SYMPTOM_SECTION_MAP.get(first, "anomalies")
