class _ElidedUtilLabel(QLabel):
    """Fixed-width util row label; elides when the stats column is narrow."""

    def __init__(self, text: str, *, column_width: int,
                 parent=None) -> None:
        super().__init__(parent)
        self._full_text = text
        self._column_width = max(STATS_UTIL_LABEL_MIN_W, int(column_width))
        self.setFixedWidth(self._column_width)
        self.setSizePolicy(QSizePolicy.Policy.Fixed, QSizePolicy.Policy.Fixed)
        self.setAlignment(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter)
        self._apply_elide()

    def set_column_width(self, width: int) -> None:
        width = max(STATS_UTIL_LABEL_MIN_W, int(width))
        if width == self._column_width:
            return
        self._column_width = width
        self.setFixedWidth(width)
        self._apply_elide()

    def _apply_elide(self) -> None:
        w = max(1, self._column_width - 2)
        self.setText(self.fontMetrics().elidedText(
            self._full_text, Qt.TextElideMode.ElideRight, w))

    def sizeHint(self) -> QSize:  # noqa: N802
        return QSize(self._column_width, STATS_UTIL_ROW_H)

    def minimumSizeHint(self) -> QSize:  # noqa: N802
        return QSize(STATS_UTIL_LABEL_MIN_W, STATS_UTIL_ROW_H)

class _StatsHoverRow(QWidget):
    """Progress-bar stat row that highlights on mouse-over."""

    def __init__(self, is_dark: bool, on_click=None, parent=None) -> None:
        super().__init__(parent)
        self._on_click = on_click
        self._hover_bg = QColor("#3A3A50") if is_dark else QColor("#E0E0EC")
        self._hovered = False
        self.setMouseTracking(True)
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
        self.setAutoFillBackground(False)
        self.setAttribute(Qt.WidgetAttribute.WA_StyledBackground, False)
        if on_click is not None:
            self.setCursor(Qt.CursorShape.PointingHandCursor)

    def _apply_hover(self, hovered: bool) -> None:
        if hovered == self._hovered:
            return
        self._hovered = hovered
        self.update()

    def track_widget(self, w: QWidget) -> None:
        """Track *w* so hover works when the pointer is over child controls."""
        w.setMouseTracking(True)
        w.installEventFilter(self)

    def enterEvent(self, event) -> None:  # noqa: N802
        self._apply_hover(True)
        super().enterEvent(event)

    def leaveEvent(self, event) -> None:  # noqa: N802
        self._apply_hover(False)
        super().leaveEvent(event)

    def eventFilter(self, obj, event) -> bool:  # noqa: N802
        et = event.type()
        if et in (QEvent.Type.Enter, QEvent.Type.HoverEnter):
            self._apply_hover(True)
        elif et in (QEvent.Type.Leave, QEvent.Type.HoverLeave):
            # Context-bound singleShot: cancelled if this row is deleteLater()'d
            # before the timer fires (e.g. statistics panel rebuild while hovering).
            QTimer.singleShot(0, self, self._sync_hover)
        elif (et == QEvent.Type.MouseButtonPress and event.button() == Qt.MouseButton.LeftButton
              and self._on_click is not None):
            self._on_click()
            return True
        return False

    def _sync_hover(self) -> None:
        # Belt-and-suspenders: context-bound timers should not fire after delete,
        # but a stale Python wrapper must not call into a destroyed C++ object.
        try:
            hovered = self.underMouse()
        except RuntimeError:
            return
        self._apply_hover(hovered)

    def update_theme(self, is_dark: bool) -> None:
        self._hover_bg = QColor("#3A3A50") if is_dark else QColor("#E0E0EC")
        if self._hovered:
            self.update()

    def paintEvent(self, event) -> None:  # noqa: N802
        if self._hovered:
            p = QPainter(self)
            p.setRenderHint(QPainter.Antialiasing, True)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QBrush(self._hover_bg))
            p.drawRoundedRect(self.rect().adjusted(0, 0, -1, -1), 2, 2)
        super().paintEvent(event)

    def mousePressEvent(self, event) -> None:  # noqa: N802
        if event.button() == Qt.MouseButton.LeftButton and self._on_click is not None:
            self._on_click()
            event.accept()
            return
        super().mousePressEvent(event)

class _IconTextButton(QWidget):
    """Clickable icon + label (macOS QPushButton QSS often suppresses setIcon)."""

    clicked = Signal()

    def __init__(self, text: str, icon_path: str, icon_color: str, *,
                 ui_fs: str, fg: str, border: str, bg: str, hover_bg: str,
                 parent=None) -> None:
        super().__init__(parent)
        self._fg = fg
        self._border = border
        self._bg = bg
        self._hover_bg = hover_bg
        self._hovered = False
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setSizePolicy(QSizePolicy.Policy.Fixed, QSizePolicy.Policy.Fixed)
        lay = QHBoxLayout(self)
        lay.setContentsMargins(8, 3, 10, 3)
        lay.setSpacing(5)
        icon_lbl = QLabel()
        icon_lbl.setPixmap(_svg_pixmap(icon_path, icon_color, 14))
        icon_lbl.setFixedSize(14, 14)
        icon_lbl.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        lay.addWidget(icon_lbl)
        text_lbl = QLabel(text)
        text_lbl.setStyleSheet(
            f"color:{fg}; font-size:{ui_fs}; font-weight:600; background:transparent;")
        text_lbl.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        lay.addWidget(text_lbl)

    def enterEvent(self, event) -> None:  # noqa: N802
        self._hovered = True
        self.update()
        super().enterEvent(event)

    def leaveEvent(self, event) -> None:  # noqa: N802
        self._hovered = False
        self.update()
        super().leaveEvent(event)

    def paintEvent(self, event) -> None:  # noqa: N802
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        bg = self._hover_bg if self._hovered else self._bg
        p.setPen(QPen(QColor(self._border)))
        p.setBrush(QBrush(QColor(bg)))
        p.drawRoundedRect(self.rect().adjusted(0, 0, -1, -1), 4, 4)
        super().paintEvent(event)

    def mousePressEvent(self, event) -> None:  # noqa: N802
        if event.button() == Qt.MouseButton.LeftButton:
            self.clicked.emit()
            event.accept()
            return
        super().mousePressEvent(event)


class _StatsPinButton(QLabel):
    """Section pin toggle (outline on hover/focus; filled when pinned).

    Uses a QLabel pixmap instead of QToolButton/QPushButton.setIcon — macOS
    application stylesheets routinely suppress tool-button icons.
    """

    clicked = Signal()

    def __init__(self, parent=None) -> None:
        super().__init__(parent)
        self.setObjectName("stats_section_pin")
        # Always reserve a narrow vertical bar (14×22) so the category badge does
        # not shift when the outline pin fades in on hover.
        self.setFixedSize(STATS_PIN_SLOT_W, STATS_PIN_SLOT_H)
        self.setSizePolicy(QSizePolicy.Policy.Fixed, QSizePolicy.Policy.Fixed)
        self.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.setAttribute(Qt.WidgetAttribute.WA_Hover, True)
        self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        self._pinned = False
        self._hovered = False
        self._row_active = False
        self._dark = True
        self._opacity_fx: Optional[QGraphicsOpacityEffect] = None
        self._refresh_icon()

    def set_row_active(self, active: bool) -> None:
        """Show outline pin while the section header row is hovered."""
        self._row_active = bool(active)
        self._refresh_icon()

    def set_pinned(self, pinned: bool, *, dark: bool = True) -> None:
        self._pinned = bool(pinned)
        self._dark = bool(dark)
        self.setToolTip(
            "Pinned — stays open with Collapse All"
            if self._pinned else
            "Pin open")
        self.setAccessibleName(
            "Unpin" if self._pinned else "Pin open")
        self._refresh_icon()

    def _pin_visible(self) -> bool:
        return bool(
            self._pinned or self._row_active or self._hovered or self.hasFocus())

    def _refresh_icon(self) -> None:
        # Always paint the icon; hide with opacity (Web ``opacity: 0``) so the
        # fixed narrow bar layout slot never collapses and the badge stays put.
        visible = self._pin_visible()
        fg = self.palette().color(QPalette.ColorRole.WindowText)
        if not fg.isValid() or fg.alpha() == 0:
            fg = QColor("#D0D0D0" if self._dark else "#555555")
        path = _IC_PIN_FILLED if self._pinned else _IC_PIN
        self.setPixmap(_svg_pixmap(path, fg.name(), STATS_PIN_ICON_PX))
        if self._opacity_fx is None:
            self._opacity_fx = QGraphicsOpacityEffect(self)
            self.setGraphicsEffect(self._opacity_fx)
        self._opacity_fx.setOpacity(1.0 if visible else 0.0)
        self.setCursor(
            Qt.CursorShape.PointingHandCursor if visible
            else Qt.CursorShape.ArrowCursor)
        self.update()

    def enterEvent(self, event) -> None:  # noqa: N802
        self._hovered = True
        self._refresh_icon()
        super().enterEvent(event)

    def leaveEvent(self, event) -> None:  # noqa: N802
        self._hovered = False
        self._refresh_icon()
        super().leaveEvent(event)

    def focusInEvent(self, event) -> None:  # noqa: N802
        self._refresh_icon()
        super().focusInEvent(event)

    def focusOutEvent(self, event) -> None:  # noqa: N802
        self._refresh_icon()
        super().focusOutEvent(event)

    def paintEvent(self, event) -> None:  # noqa: N802
        if self._pin_visible() and (self._hovered or self.hasFocus()):
            p = QPainter(self)
            p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QBrush(QColor(128, 128, 128, 70)))
            p.drawRoundedRect(self.rect().adjusted(1, 1, -1, -1), 3, 3)
            p.end()
        super().paintEvent(event)

    def mousePressEvent(self, event) -> None:  # noqa: N802
        if event.button() == Qt.MouseButton.LeftButton:
            # Invisible (opacity-0) pin must not steal clicks — Web uses
            # pointer-events: none for the same state.
            if not self._pin_visible():
                event.ignore()
                return
            self.clicked.emit()
            event.accept()
            return
        super().mousePressEvent(event)


class _StatsHeaderHoverFilter(QObject):
    """Reveal the outline pin while the header row is hovered."""

    def __init__(self, pin: _StatsPinButton) -> None:
        super().__init__(pin)
        self._pin = pin

    def eventFilter(self, obj, event) -> bool:  # noqa: N802
        et = event.type()
        if et in (QEvent.Type.Enter, QEvent.Type.HoverEnter):
            self._pin.set_row_active(True)
        elif et in (QEvent.Type.Leave, QEvent.Type.HoverLeave):
            self._pin.set_row_active(False)
        return False


_STATS_SECTION_MIME = "application/x-btf-stats-section"


class _StatsSectionDragFilter(QObject):
    """Drag a statistics section header to reorder sections in the panel."""

    def __init__(self, panel: "_StatsPanel", section_id: str,
                 grip: QWidget) -> None:
        super().__init__(panel)
        self._panel = panel
        self._section_id = section_id
        self._grip = grip
        self._press_pos: Optional[QPoint] = None

    def eventFilter(self, obj, event) -> bool:  # noqa: N802
        et = event.type()
        if obj is self._grip:
            if et == QEvent.Type.MouseButtonPress:
                if event.button() == Qt.MouseButton.LeftButton:
                    self._press_pos = event.position().toPoint()
            elif et == QEvent.Type.MouseButtonRelease:
                self._press_pos = None
            elif et == QEvent.Type.MouseMove:
                if (self._press_pos is not None
                    and event.buttons() & Qt.MouseButton.LeftButton):
                    delta = event.position().toPoint() - self._press_pos
                    if delta.manhattanLength() >= QApplication.startDragDistance():
                        self._press_pos = None
                        drag = QDrag(obj)
                        mime = QMimeData()
                        mime.setData(
                            _STATS_SECTION_MIME,
                            self._section_id.encode("utf-8"))
                        mime.setText(self._section_id)
                        drag.setMimeData(mime)
                        self._panel._begin_section_drag(self._section_id)
                        try:
                            drag.exec(Qt.DropAction.MoveAction)
                        finally:
                            self._panel._end_section_drag()
                        return True
        if et == QEvent.Type.DragEnter:
            if event.mimeData().hasFormat(_STATS_SECTION_MIME):
                event.acceptProposedAction()
                self._panel._set_section_drop_target(self._section_id)
                return True
        elif et == QEvent.Type.DragMove:
            if event.mimeData().hasFormat(_STATS_SECTION_MIME):
                event.acceptProposedAction()
                self._panel._set_section_drop_target(self._section_id)
                return True
        elif et == QEvent.Type.Drop:
            if event.mimeData().hasFormat(_STATS_SECTION_MIME):
                raw = bytes(event.mimeData().data(_STATS_SECTION_MIME))
                src = raw.decode("utf-8", errors="ignore").strip()
                self._panel._set_section_drop_target(None)
                if src:
                    self._panel._on_section_drop(src, self._section_id)
                event.acceptProposedAction()
                return True
        return False


class _UtilScrollResizeFilter(QObject):
    """Keep util rows inside the scroll viewport when the panel is resized."""

    def __init__(self, panel: "_StatsPanel", scroll: QScrollArea,
                 inner: QWidget) -> None:
        super().__init__(panel)
        self._panel = panel
        self._scroll = scroll
        self._inner = inner

    def pin_inner_width(self) -> None:
        vw = self._scroll.viewport().width()
        if vw > 0:
            self._inner.setMaximumWidth(vw)
            self._inner.setMinimumWidth(0)

    def eventFilter(self, obj, event) -> bool:  # noqa: N802
        if event.type() == QEvent.Type.Resize:
            self.pin_inner_width()
            QTimer.singleShot(0, self._panel.sync_util_layout)
        return False

class _StatsPanelViewportFilter(QObject):
    """Keep stats content within the visible scroll viewport width."""

    def __init__(self, panel: "_StatsPanel") -> None:
        super().__init__(panel)
        self._panel = panel

    def eventFilter(self, obj, event) -> bool:  # noqa: N802
        if event.type() == QEvent.Type.Resize:
            self._panel._pin_main_inner_width()
            # Keep pin pad sized while a demo/AI scroll pin is active; otherwise
            # leave the tail at 0 so the last section has no blank below it.
            self._panel._update_scroll_tail_height()
            QTimer.singleShot(0, self._panel.sync_util_layout)
        return False

class _StatsTableHoverFilter(QObject):
    """Clear stats-table row hover highlight when the pointer leaves the table."""

    def __init__(self, clear_fn) -> None:
        super().__init__()
        self._clear_fn = clear_fn

    def eventFilter(self, obj, event) -> bool:  # noqa: N802
        if event.type() == QEvent.Type.Leave:
            self._clear_fn()
        return False

class _StatsItemDelegate(QStyledItemDelegate):
    """Paint stats-table cells (background fill + text) ourselves instead of
    delegating to `QStyle::drawControl(CE_ItemViewItem, ...)`.

    Some native/desktop QStyle plugins (GTK/Breeze-style integration, some
    style-sheet-proxy configurations, etc.) do not honour a
    `QTableWidgetItem`'s `Qt::BackgroundRole` brush when painting item-view
    cells, which silently defeats per-row hover highlighting set via
    `item.setBackground(...)` — even though the underlying item data is
    correct and the exact same code renders fine under Qt's own Fusion/
    offscreen style. Painting the background and text directly bypasses
    QStyle/QSS entirely for this one aspect, so the highlight is guaranteed
    to be visible regardless of the active widget style. Stats-table items
    are plain text cells (no icons/checkboxes), so a minimal re-implementation
    is sufficient.
    """

    def paint(self, painter: QPainter, option, index) -> None:  # noqa: N802
        painter.save()
        opt_state = option.state
        if opt_state & QStyle.StateFlag.State_Selected:
            painter.fillRect(option.rect, option.palette.color(
                QPalette.ColorGroup.Active, QPalette.ColorRole.Highlight))
            pen_color = option.palette.color(
                QPalette.ColorGroup.Active, QPalette.ColorRole.HighlightedText)
        else:
            bg = index.data(Qt.ItemDataRole.BackgroundRole)
            if isinstance(bg, QBrush) and bg.style() != Qt.BrushStyle.NoBrush:
                painter.fillRect(option.rect, bg)
            fg = index.data(Qt.ItemDataRole.ForegroundRole)
            pen_color = (fg.color() if isinstance(fg, QBrush) and
                         fg.style() != Qt.BrushStyle.NoBrush else
                         option.palette.color(QPalette.ColorRole.Text))
        painter.setPen(pen_color)
        font = index.data(Qt.ItemDataRole.FontRole)
        painter.setFont(font if isinstance(font, QFont) else option.font)
        align = index.data(Qt.ItemDataRole.TextAlignmentRole)
        align = int(align) if align is not None else int(
            Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter)
        text = index.data(Qt.ItemDataRole.DisplayRole)
        rect = option.rect.adjusted(3, 0, -3, 0)
        painter.drawText(rect, align, "" if text is None else str(text))
        painter.restore()

class _StatsTableBodyCursorFilter(QObject):
    """Pointing-hand cursor over clickable table cells only (not resize grips)."""

    def __init__(self, table: QTableWidget) -> None:
        super().__init__(table)
        self._table = table
        self._armed = False

    def eventFilter(self, obj, event) -> bool:  # noqa: N802
        et = event.type()
        if et == QEvent.Type.MouseMove:
            if self._table.indexAt(event.position().toPoint()).isValid():
                obj.setCursor(Qt.CursorShape.PointingHandCursor)
                self._armed = True
            elif self._armed:
                obj.unsetCursor()
                self._armed = False
        elif et == QEvent.Type.Leave:
            if self._armed:
                obj.unsetCursor()
                self._armed = False
        return False

class _StatsSortItem(QTableWidgetItem):
    """Table cell that sorts by an explicit key (numeric/time) instead of display text."""

    def __init__(self, text, sort_key=None) -> None:
        super().__init__(str(text))
        self._sort_key = sort_key if sort_key is not None else str(text).lower()

    def __lt__(self, other) -> bool:  # noqa: N802
        if isinstance(other, _StatsSortItem):
            a, b = self._sort_key, other._sort_key
            if isinstance(a, (int, float)) and isinstance(b, (int, float)):
                return a < b
            return str(a).lower() < str(b).lower()
        return super().__lt__(other)

class _StatsSectionGrip(QWidget):
    """Horizontal drag handle below a stats table to adjust its max height."""

    height_changed = Signal(int)

    _MIN_H = 80
    _MAX_H = 480

    def __init__(self, is_dark: bool, get_height_fn, parent=None,
                 *, min_h: Optional[int] = None) -> None:
        super().__init__(parent)
        self._is_dark = is_dark
        self._get_height = get_height_fn
        self._min_h = self._MIN_H if min_h is None else int(min_h)
        self._dragging = False
        self._start_y = 0
        self._start_h = STATS_TABLE_DEFAULT_H
        self.setFixedHeight(8)
        self.setCursor(Qt.CursorShape.SizeVerCursor)
        self.setToolTip("Drag to resize table height")
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
        self.setMouseTracking(True)
        self.setAttribute(Qt.WidgetAttribute.WA_Hover, True)

    def set_dark(self, is_dark: bool) -> None:
        self._is_dark = is_dark
        self.update()

    def _event_global_y(self, event) -> int:
        gp = event.globalPosition() if hasattr(event, "globalPosition") else None
        if gp is not None:
            return int(gp.y())
        return int(event.globalY())

    def _drag_start(self, global_y: int) -> None:
        """Begin a resize drag. grabMouse() works on macOS; the app filter is a
        Wayland backup. Do not swallow filtered events or Cocoa can drop the
        matching mouse-release."""
        self._dragging = True
        self._start_y = global_y
        self._start_h = self._get_height()
        _HoverCursor.show(Qt.CursorShape.SizeVerCursor)
        self.grabMouse()
        app = QApplication.instance()
        if app:
            app.installEventFilter(self)

    def _drag_move(self, global_y: int) -> None:
        _HoverCursor.show(Qt.CursorShape.SizeVerCursor)
        delta = global_y - self._start_y
        self.height_changed.emit(
            max(self._min_h, min(self._MAX_H, self._start_h + delta)))

    def _drag_end(self) -> None:
        if not self._dragging:
            _HoverCursor.hide(Qt.CursorShape.SizeVerCursor)
            return
        self._dragging = False
        if QWidget.mouseGrabber() is self:
            self.releaseMouse()
        app = QApplication.instance()
        if app:
            app.removeEventFilter(self)
        _HoverCursor.hide(Qt.CursorShape.SizeVerCursor)

    def eventFilter(self, obj, event) -> bool:  # noqa: N802
        """Follow the pointer during drag without consuming the event."""
        if not self._dragging:
            return False
        et = event.type()
        if et == QEvent.Type.MouseMove:
            if not (QApplication.mouseButtons() & Qt.MouseButton.LeftButton):
                self._drag_end()
                return False
            self._drag_move(self._event_global_y(event))
            return False
        if et == QEvent.Type.MouseButtonRelease and event.button() == Qt.MouseButton.LeftButton:
            self._drag_end()
            return False
        return False

    def mousePressEvent(self, event) -> None:  # noqa: N802
        if event.button() == Qt.MouseButton.LeftButton:
            self._drag_start(self._event_global_y(event))
            event.accept()
            return
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event) -> None:  # noqa: N802
        if self._dragging:
            if not (event.buttons() & Qt.MouseButton.LeftButton):
                self._drag_end()
                event.accept()
                return
            self._drag_move(self._event_global_y(event))
            event.accept()
            return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event) -> None:  # noqa: N802
        if event.button() == Qt.MouseButton.LeftButton and self._dragging:
            self._drag_end()
            event.accept()
            return
        super().mouseReleaseEvent(event)

    def enterEvent(self, event) -> None:  # noqa: N802
        self.update()
        super().enterEvent(event)

    def leaveEvent(self, event) -> None:  # noqa: N802
        if not self._dragging:
            _HoverCursor.hide(Qt.CursorShape.SizeVerCursor)
        self.update()
        super().leaveEvent(event)

    def hideEvent(self, event) -> None:  # noqa: N802
        if self._dragging:
            self._drag_end()
        else:
            _HoverCursor.hide(Qt.CursorShape.SizeVerCursor)
        super().hideEvent(event)

    def paintEvent(self, event) -> None:  # noqa: N802
        super().paintEvent(event)
        p = QPainter(self)
        if self.underMouse() or self._dragging:
            c = QColor("#6688CC")
        else:
            c = QColor("#3C3C3C" if self._is_dark else "#DDDDDD")
        y = self.height() // 2
        p.setPen(QPen(c, 1))
        p.drawLine(0, y, self.width(), y)
        p.end()


class _CompareBarChart(QWidget):
    """Theme-aware Core Util paired bars or Response/Summary/Migration diverging bars."""

    def __init__(self, kind: str, parent=None) -> None:
        super().__init__(parent)
        self._kind = kind if kind in ("util", "p99", "summary", "heatmap") else "util"
        self._rows: List[dict] = []
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
        self.setMinimumHeight(0)
        self.hide()

    def set_rows(self, rows: Sequence[dict]) -> None:
        self._rows = [r for r in (rows or []) if isinstance(r, dict)]
        n = len(self._rows)
        if not n:
            self.hide()
            self.setFixedHeight(0)
            self.update()
            return
        row_h = 32 if self._kind == "util" else 22
        header = 26 if self._kind == "util" else 44
        self.setFixedHeight(header + n * row_h + 8)
        self.show()
        self.update()

    def paintEvent(self, event) -> None:  # noqa: N802
        del event
        rows = self._rows
        if not rows:
            return
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        pal = self.palette()
        ink = pal.color(QPalette.ColorRole.WindowText)
        muted = QColor(ink)
        muted.setAlpha(170)
        w = self.width()
        pad = 8
        label_w = 78 if self._kind == "util" else 96
        right_w = 52 if self._kind == "util" else 88
        plot_x = pad + label_w
        plot_w = max(40.0, w - plot_x - right_w - pad)
        header_h = 22 if self._kind == "util" else 40
        p.setPen(ink)
        p.setFont(self.font())
        if self._kind == "util":
            title = "Core utilisation"
        elif self._kind == "summary":
            title = "Summary changes"
        elif self._kind == "heatmap":
            title = "Migration Δ"
        else:
            title = "Response P99 change"
        p.drawText(pad, 16, title)
        p.setPen(muted)
        if self._kind == "util":
            p.drawText(QRectF(w - pad - 220, 2, 220, 16),
                       int(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter),
                       "Baseline A · Candidate B")
            max_v = max((max(float(r.get("a") or 0), float(r.get("b") or 0)) for r in rows), default=1.0)
            max_v = max(max_v, 1.0)
            for i, row in enumerate(rows):
                y = header_h + 4 + i * 32
                p.setPen(ink)
                p.drawText(QRectF(pad, y, label_w - 6, 28),
                           int(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter),
                           str(row.get("label") or "")[:18])
                a_v = max(0.0, float(row.get("a") or 0))
                b_v = max(0.0, float(row.get("b") or 0))
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(QColor("#2a6fb2"))
                p.drawRoundedRect(QRectF(plot_x, y + 2, max(2.0, plot_w * a_v / max_v), 9), 3, 3)
                p.setBrush(QColor("#6b4ea8"))
                p.drawRoundedRect(QRectF(plot_x, y + 14, max(2.0, plot_w * b_v / max_v), 9), 3, 3)
                p.setPen(QColor("#2a6fb2"))
                p.drawText(QRectF(plot_x + plot_w + 6, y, right_w, 12),
                           int(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter),
                           f"{a_v:.1f}%")
                p.setPen(QColor("#6b4ea8"))
                p.drawText(QRectF(plot_x + plot_w + 6, y + 12, right_w, 12),
                           int(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter),
                           f"{b_v:.1f}%")
        else:
            subtitle = "Δ = A − B" if self._kind == "heatmap" else "Candidate B − Baseline A"
            p.drawText(QRectF(w - pad - 220, 2, 220, 16),
                       int(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter),
                       subtitle)
            max_v = max((abs(float(r.get("cand") or r.get("delta") or 0)) for r in rows), default=1.0) or 1.0
            mid = plot_x + plot_w / 2.0
            half = plot_w / 2.0
            p.setPen(QColor("#3cb371"))
            p.drawText(QRectF(plot_x, 22, plot_w / 2.0, 14),
                       int(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter),
                       "Improved")
            p.setPen(QColor("#e07070"))
            p.drawText(QRectF(plot_x + plot_w / 2.0, 22, plot_w / 2.0, 14),
                       int(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter),
                       "Regressed")
            p.setPen(QPen(QColor("#888888"), 1))
            p.drawLine(int(mid), header_h, int(mid), self.height() - 6)
            for i, row in enumerate(rows):
                y = header_h + 4 + i * 22
                p.setPen(ink)
                p.drawText(QRectF(pad, y, label_w - 6, 18),
                           int(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter),
                           str(row.get("label") or "")[:16])
                if "cand" in row:
                    cand = float(row.get("cand") or 0)
                else:
                    # heatmap stores table Δ = A−B; chart wants B−A
                    cand = -float(row.get("delta") or 0)
                bar_w = abs(cand) / max_v * half
                color = QColor("#e07070") if cand > 0 else QColor("#3cb371")
                x = mid if cand >= 0 else mid - bar_w
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(color)
                p.drawRoundedRect(QRectF(x, y + 3, max(2.0, bar_w), 12), 2, 2)
                p.setPen(color)
                change = str(row.get("change") or "")
                if not change and self._kind == "heatmap":
                    d = float(row.get("delta") or 0)
                    change = f"{'+' if d > 0 else '−'}{abs(int(d))}" if d else "0"
                p.drawText(QRectF(plot_x + plot_w + 6, y, right_w, 18),
                           int(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter),
                           change)
        p.end()


class _CompareNavPages(QWidget):
    """Grouped left-rail navigation (``QListWidget``) + ``QStackedWidget``,
    mirroring the web Trace Compare dialog's ``.compare-rail`` groups.

    Exposes the slice of the ``QTabWidget`` surface the dialog and its tests
    rely on (``addTab`` / ``count`` / ``currentIndex`` / ``setCurrentIndex`` /
    ``widget`` / ``tabText`` / ``currentChanged``) so nothing else in
    ``_TraceCompareDialog`` had to change.
    """

    currentChanged = Signal(int)

    # tab label -> section header (same grouping as web pageTabs `group`).
    _GROUPS = {
        "Summary": "Overview",
        "Top Tasks": "CPU & Cores",
        "Core Util": "CPU & Cores",
        "Core Migrations": "CPU & Cores",
        "Execution": "Timing",
        "Blocking": "Timing",
        "Inter-Arrival": "Timing",
        "Response": "Timing",
        "Preemption": "Contention",
        "Sync": "Contention",
        "Mutex": "Contention",
        "Trends": "Cross-trace",
    }

    def __init__(self, parent=None) -> None:
        super().__init__(parent)
        self._labels: List[str] = []
        # Match the Analysis Findings dialog's left list: explicit UI font
        # (macOS ignores CSS font-size on the native item delegate), blue-tint
        # hover/selection, 2px 6px item padding.
        ui_pt = max(6, min(int(UI_FONT_SIZE), 24))
        ui_font = _application_ui_font(ui_pt)
        ui_fs = _ui_font_stylesheet_size(ui_pt)
        try:
            _dark = QApplication.instance().palette().color(
                QPalette.Window).lightness() < 128
        except Exception:
            _dark = True
        ink = "#c5d0dc" if _dark else "#1E1E1E"
        muted = "#9a9a9a" if _dark else "#555555"
        self._hdr_ink = QColor(muted)
        self._hdr_bg = QColor(255, 255, 255, 20) if _dark else QColor(0, 0, 0, 16)
        row = QHBoxLayout(self)
        row.setContentsMargins(0, 0, 0, 0)
        row.setSpacing(0)
        self._list = QListWidget()
        self._list.setObjectName("compareRail")
        self._list.setFixedWidth(178)
        self._list.setFont(ui_font)
        self._list.setSpacing(0)
        self._list.setWordWrap(False)
        self._list.setTextElideMode(Qt.TextElideMode.ElideRight)
        self._list.setFrameShape(QFrame.Shape.NoFrame)
        self._list.setHorizontalScrollBarPolicy(
            Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        _hdr_css = ("rgba(255,255,255,0.08)" if _dark else "rgba(0,0,0,0.06)")
        self._list.setStyleSheet(
            f"QListWidget#compareRail {{ padding: 0; outline: none;"
            f" border: none; background: transparent;"
            f" font-size: {ui_fs}; color: {ink}; }}"
            "QListWidget#compareRail::item { padding: 4px 8px; margin: 1px 6px;"
            " border-radius: 4px; border-left: 2px solid transparent; }"
            "QListWidget#compareRail::item:hover:!selected:enabled {"
            " background: rgba(127, 127, 127, 0.14); }"
            "QListWidget#compareRail::item:selected {"
            " background: transparent; color: #4a9eff;"
            " border-left-color: #4a9eff; }"
            # Section header (NoItemFlags -> disabled): full-width gray band,
            # same font as the items, bold — matches web .compare-rail-group.
            f"QListWidget#compareRail::item:disabled {{ margin: 6px 0 2px;"
            f" padding: 4px 14px; border-radius: 0; border-left: 0;"
            f" background: {_hdr_css}; color: {muted}; }}"
        )
        self._stack = QStackedWidget()
        row.addWidget(self._list)
        row.addWidget(self._stack, 1)
        self._list.currentRowChanged.connect(self._on_row)

    def _on_row(self, _row: int) -> None:
        it = self._list.currentItem()
        if it is None:
            return
        idx = it.data(Qt.ItemDataRole.UserRole)
        if idx is None:  # a section header — not selectable, ignore
            return
        self._stack.setCurrentIndex(int(idx))
        self.currentChanged.emit(int(idx))

    def _has_group(self, name: str) -> bool:
        for i in range(self._list.count()):
            if self._list.item(i).data(Qt.ItemDataRole.UserRole + 1) == name:
                return True
        return False

    # --- QTabWidget-compatible surface -----------------------------------
    def addTab(self, widget: QWidget, label: str) -> int:
        page_idx = self._stack.count()
        group = self._GROUPS.get(label, "Cross-trace")
        if not self._has_group(group):
            hdr = QListWidgetItem(group.upper())
            hdr.setFlags(Qt.ItemFlag.NoItemFlags)
            hdr.setData(Qt.ItemDataRole.UserRole + 1, group)
            f = hdr.font()          # same size as the items; just bold
            f.setBold(True)
            hdr.setFont(f)
            hdr.setForeground(self._hdr_ink)
            hdr.setBackground(self._hdr_bg)
            self._list.addItem(hdr)
        item = QListWidgetItem(label)
        item.setData(Qt.ItemDataRole.UserRole, page_idx)
        self._list.addItem(item)
        self._stack.addWidget(widget)
        self._labels.append(label)
        if self._stack.count() == 1:
            self._list.setCurrentItem(item)
        return page_idx

    def count(self) -> int:
        return self._stack.count()

    def currentIndex(self) -> int:
        return self._stack.currentIndex()

    def setCurrentIndex(self, idx: int) -> None:
        for i in range(self._list.count()):
            if self._list.item(i).data(Qt.ItemDataRole.UserRole) == idx:
                self._list.setCurrentRow(i)
                return
        self._stack.setCurrentIndex(idx)

    def widget(self, idx: int) -> QWidget:
        return self._stack.widget(idx)

    def tabText(self, idx: int) -> str:
        return self._labels[idx] if 0 <= idx < len(self._labels) else ""


