        def _populate_distrib(blay: QVBoxLayout) -> None:
            evs = self._ux_events(trace, lo, hi)
            disp = self._dispatch_sample_map(trace, lo, hi)
            metric = QComboBox()
            labels = {
                "exec": "Execution", "block": "Blocking", "inter": "Inter-arrival",
                "response": "Response", "dispatch": "Dispatch",
                "wakeup": "Wake (stand-in)", "preempt": "Preemption",
            }
            for kind in DISTRIBUTION_KINDS:
                metric.addItem(labels.get(kind, kind), kind)
            task_box = QComboBox()
            names = []
            seen = set()
            for r in unified_jitter(evs, disp):
                mk = str(r.get("mk") or "")
                if mk and mk not in seen:
                    seen.add(mk)
                    names.append((str(r.get("task") or mk), mk))
            if not names:
                task_box.addItem("(no tasks)", "")
            else:
                for lab, mk in names:
                    task_box.addItem(lab, mk)
            summary = self._lbl("Select a task to see n / p50 / p99 / sparkline.",
                                color="#888888", ui_fs=_fs)
            summary.setTextInteractionFlags(
                Qt.TextInteractionFlag.TextSelectableByMouse)
            hist = _HistogramWidget(
                [], trace.time_scale, QColor("#5B9BD5"), self._is_dark,
                value_as_time=True, show_variability=True)
            # Fixed height — Expanding steals space from Metric/Task and the
            # Open histogram / Query with AI… row when the stats dock is short.
            hist.setFixedHeight(200)
            hist.setSizePolicy(
                QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
            scale_box = QComboBox()
            scale_box.addItems(["Auto", "Linear", "p5–p95", "Log duration"])

            def _on_scale(index: int) -> None:
                modes = ("auto", "linear", "percentile", "log")
                hist.set_scale_mode(modes[index] if 0 <= index < 4 else "auto")

            scale_box.currentIndexChanged.connect(_on_scale)

            def _refresh_summary() -> None:
                mk = str(task_box.currentData() or "")
                kind = str(metric.currentData() or "exec")
                samples = distribution_metric_samples(evs, kind, mk, disp) if mk else []
                hist.set_values(samples)
                open_btn.setEnabled(bool(mk))
                self._distrib_has_task = bool(mk)
                self._sync_distrib_query_ai_btn()
                if not mk:
                    summary.setText("Select a task to see n / p50 / p99 / sparkline.")
                    return
                model = distribution_explorer(evs, kind, mk, disp)
                if not model:
                    summary.setText("No samples for this metric × task in scope.")
                    return
                scale = trace.time_scale
                summary.setText(
                    f"n={model.get('n') or 0}  min={_format_time(int(model.get('min_ns') or 0), scale)}  "
                    f"p50={_format_time(int(model.get('p50_ns') or 0), scale)}  "
                    f"p99={_format_time(int(model.get('p99_ns') or 0), scale)}  "
                    f"max={_format_time(int(model.get('max_ns') or 0), scale)}  "
                    f"CV={float(model.get('cv') or 0) * 100:.1f}%  "
                    f"{model.get('spark') or ''}"
                )

            def _open(_checked: bool = False) -> None:
                mk = str(task_box.currentData() or "")
                kind = str(metric.currentData() or "exec")
                if not mk:
                    return
                model = distribution_explorer(evs, kind, mk, disp) or {}
                plot_kind = str(model.get("plot_kind") or kind)
                preemptor = None
                if plot_kind == "preempt":
                    ranks = preemptor_ranking(preemption_pairs(evs), 16)
                    rec = next(
                        (r for r in ranks if str(r.get("mk") or "") == mk),
                        None,
                    )
                    tops = (rec or {}).get("top") or []
                    if tops:
                        preemptor = str(
                            tops[0].get("task") or tops[0].get("mk") or "")
                    if not preemptor:
                        return
                self._open_plot(trace, mk, plot_kind, preemptor=preemptor)

            def _query_ai(_checked: bool = False) -> None:
                mk = str(task_box.currentData() or "")
                kind = str(metric.currentData() or "exec")
                self._query_distrib_explorer_ai(mk, kind)

            metric.currentIndexChanged.connect(lambda _i: _refresh_summary())
            task_box.currentIndexChanged.connect(lambda _i: _refresh_summary())
            open_btn = QPushButton("Open histogram")
            open_btn.setSizePolicy(
                QSizePolicy.Policy.Minimum, QSizePolicy.Policy.Fixed)
            open_btn.setMinimumHeight(22)
            self._style_stats_tool_button(open_btn)
            open_btn.clicked.connect(_open)
            self._distrib_open_btn = open_btn
            ai_btn = QPushButton("Query with AI…")
            ai_btn.setSizePolicy(
                QSizePolicy.Policy.Minimum, QSizePolicy.Policy.Fixed)
            ai_btn.setMinimumHeight(22)
            self._style_stats_tool_button(ai_btn)
            ai_btn.clicked.connect(_query_ai)
            self._distrib_ai_btn = ai_btn
            self._sync_distrib_query_ai_btn()
            combo_pol = QSizePolicy(
                QSizePolicy.Policy.Preferred, QSizePolicy.Policy.Fixed)
            metric.setSizePolicy(combo_pol)
            task_box.setSizePolicy(combo_pol)
            metric.setMinimumWidth(72)
            task_box.setMinimumWidth(72)
            # Container widget (not a bare nested layout) so the toolbar keeps
            # a non-zero height when the section body is height-constrained.
            tools_w = QWidget()
            tools_w.setSizePolicy(
                QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
            tools = QVBoxLayout(tools_w)
            tools.setContentsMargins(0, 0, 0, 0)
            tools.setSpacing(4)
            sel = QHBoxLayout()
            sel.setSpacing(6)
            sel.addWidget(QLabel("Metric"))
            sel.addWidget(metric, 1)
            sel.addWidget(QLabel("Task"))
            sel.addWidget(task_box, 1)
            tools.addLayout(sel)
            hist_btns = QHBoxLayout()
            hist_btns.setSpacing(6)
            hist_btns.addWidget(open_btn, 1)
            hist_btns.addWidget(ai_btn, 1)
            tools.addLayout(hist_btns)
            blay.addWidget(tools_w)
            blay.addWidget(summary)
            scale_row_w = QWidget()
            scale_row_w.setSizePolicy(
                QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
            scale_row = QHBoxLayout(scale_row_w)
            scale_row.setContentsMargins(0, 0, 0, 0)
            scale_row.addWidget(QLabel("Histogram scale"))
            scale_row.addWidget(scale_box)
            scale_row.addStretch(1)
            blay.addWidget(scale_row_w)
            blay.addWidget(hist)
            _refresh_summary()

        self._add_collapsible_section(
            "distrib", f"Distribution Explorer{scope}", _fs, _populate_distrib,
        )

        # -- Preemption Chain Analysis ----------------------------------------
        empty_preempt = ("No preemption events in cursor range" if scope
                         else "No preemption events found (single-task or idle-only trace)")

        def _populate_preempt(blay: QVBoxLayout) -> None:
            _preempt_rows, _preempt_truncated = _preemption_chain_rows(trace, lo, hi)
            if _preempt_truncated:
                blay.addWidget(self._lbl(
                    f"Showing top {PREEMPTION_CHAIN_MAX_ROWS:,} pairs by total preemption time.",
                    color="#888888", ui_fs=_fs))
            blay.addWidget(self._build_preemption_table(
                _preempt_rows, _fs, empty_preempt,
                on_row_click=lambda mk, preemptor: self._open_plot(
                    trace, mk, "preempt", preemptor=preemptor),
            ))

        self._add_collapsible_section(
            "preemption",
            f"Preemption Chain Analysis{scope}",
            _fs,
            _populate_preempt,
        )

        def _populate_preempt_matrix(blay: QVBoxLayout) -> None:
            evs = self._ux_events(trace, lo, hi)
            pairs = preemption_pairs(evs)
            ranks = preemptor_ranking(pairs, 16)
            matrix = preemption_matrix(pairs, 12)
            scale = trace.time_scale
            blay.addWidget(self._build_click_rows_table(
                ranks,
                ["Victim", "Count", "Total", "Max", "Top preemptors", "Story"],
                lambda r: [
                    r.get("task") or "",
                    r.get("count") or 0,
                    _format_time(int(r.get("total_ns") or 0), scale),
                    _format_time(int(r.get("max_ns") or 0), scale),
                    r.get("top_label") or "",
                    r.get("story") or "",
                ],
                lambda r: r.get("worst") or r,
                _fs, "No preemption overlaps in this scope",
                "preempt_matrix", trace,
                keys_fn=lambda r: [
                    str(r.get("task") or "").lower(),
                    int(r.get("count") or 0),
                    int(r.get("total_ns") or 0),
                    int(r.get("max_ns") or 0),
                    str(r.get("top_label") or "").lower(),
                    str(r.get("story") or "").lower(),
                ],
            ))
            tasks = matrix.get("tasks") or []
            cells = matrix.get("cells") or {}
            if tasks:
                headers = ["Victim \\ Preemptor"] + [
                    t.get("task") or t.get("mk") for t in tasks]
                table = self._make_plain_stats_table(headers, _fs)
                table.setRowCount(len(tasks))
                bg = QBrush(self._stats_table_colors()[0])
                link = QBrush(QColor("#88AAFF"))
                for r, victim in enumerate(tasks):
                    item = self._stats_sort_item(
                        str(victim.get("task") or ""),
                        str(victim.get("task") or "").lower(), bg)
                    table.setItem(r, 0, item)
                    for c, col in enumerate(tasks, start=1):
                        rec = cells.get(f"{victim.get('mk')}|{col.get('mk')}") or {}
                        ns = int(rec.get("ns") or 0)
                        cell = self._stats_sort_item(
                            _format_time(ns, scale) if ns and victim.get("mk") != col.get("mk") else "—",
                            ns, bg)
                        if ns and victim.get("mk") != col.get("mk"):
                            cell.setForeground(link)
                            cell.setData(Qt.ItemDataRole.UserRole, rec)
                        table.setItem(r, c, cell)

                def _pm_clicked(_row: int, col: int) -> None:
                    if col <= 0:
                        return
                    item = table.item(_row, col)
                    if item is None:
                        return
                    rec = item.data(Qt.ItemDataRole.UserRole)
                    if isinstance(rec, dict) and rec.get("ns"):
                        self._activate_ux_event(trace, {
                            **rec,
                            "mk": rec.get("victim") or "",
                            "task": rec.get("victim") or "",
                            "duration": rec.get("ns"),
                            "section": "preempt_matrix",
                        })

                table.cellClicked.connect(_pm_clicked)
                self._wire_stats_table_click_cursor(table)
                self._wire_stats_table_row_hover(table)
                table.resizeColumnsToContents()
                table.setSortingEnabled(True)
                self._wrap_table_with_resizer(blay, table, "preempt_matrix")

        self._add_collapsible_section(
            "preempt_matrix", f"Preemption Matrix{scope}", _fs,
            _populate_preempt_matrix,
        )

        # -- Priority inheritance ---------------------------------------------
        if trace.has_priority_instrumentation:
            empty_priority = ("No priority boosts in cursor range" if scope
                              else "No priority boosts in trace")

            def _populate_priority(blay: QVBoxLayout) -> None:
                _priority_rows = _priority_stats_rows(trace, lo, hi)
                host = QWidget()
                play = QVBoxLayout(host)
                play.setContentsMargins(0, 0, 0, 0)
                if not _priority_rows:
                    play.addWidget(self._lbl(empty_priority, color="#888888", ui_fs=_fs))
                else:
                    headers = ["Task", "Base", "Peak", "Boosts", "Boosted", "Pattern"]
                    table = QTableWidget(len(_priority_rows), len(headers))
                    table.setHorizontalHeaderLabels(headers)
                    table.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)
                    table.setSelectionMode(QAbstractItemView.SelectionMode.NoSelection)
                    table.setFocusPolicy(Qt.FocusPolicy.NoFocus)
                    table.verticalHeader().setVisible(False)
                    table.horizontalHeader().setStretchLastSection(True)
                    table.setShowGrid(False)
                    table.setFrameShape(QFrame.NoFrame)
                    table.verticalHeader().setDefaultSectionSize(STATS_TABLE_ROW_H)
                    table.verticalHeader().setMinimumSectionSize(STATS_TABLE_ROW_H)
                    table.verticalHeader().setSectionResizeMode(QHeaderView.ResizeMode.Fixed)
                    table.horizontalHeader().setSectionsClickable(True)
                    table.horizontalHeader().setSortIndicatorShown(True)
                    self._apply_stats_table_theme(table, _fs)
                    _item_bg = QBrush(self._stats_table_colors()[0])
                    _priority_align = [
                        Qt.AlignmentFlag.AlignLeft, Qt.AlignmentFlag.AlignRight,
                        Qt.AlignmentFlag.AlignRight, Qt.AlignmentFlag.AlignRight,
                        Qt.AlignmentFlag.AlignRight, Qt.AlignmentFlag.AlignLeft,
                    ]
                    for ri, row in enumerate(_priority_rows):
                        mk, label, base, peak, count, total, pattern, total_ns = row
                        vals = [label, str(base), str(peak), str(count), total, pattern]
                        sort_keys = [
                            label.lower(), base, peak, count, total_ns, pattern.lower(),
                        ]
                        for ci, val in enumerate(vals):
                            item = _StatsSortItem(val, sort_keys[ci])
                            item.setFlags(Qt.ItemFlag.ItemIsEnabled)
                            item.setBackground(_item_bg)
                            item.setTextAlignment(_priority_align[ci] | Qt.AlignmentFlag.AlignVCenter)
                            if ci == 0:
                                item.setData(Qt.ItemDataRole.UserRole, mk)
                            if ci == 5 and "L/M/H" in pattern:
                                item.setForeground(QBrush(QColor("#E74C3C")))
                            table.setItem(ri, ci, item)
                    table.setSortingEnabled(True)

                    def _on_priority_row_clicked(row: int, _col: int) -> None:
                        item = table.item(row, 0)
                        if item is None:
                            return
                        mk = item.data(Qt.ItemDataRole.UserRole)
                        if mk:
                            self._open_priority_plot(trace, mk)

                    table.cellClicked.connect(_on_priority_row_clicked)
                    self._wire_stats_table_click_cursor(table)
                    self._wire_stats_table_row_hover(table)
                    self._wrap_table_with_resizer(play, table, "priority")
                blay.addWidget(host)

            self._add_collapsible_section(
                "priority",
                f"Priority Inheritance{scope}",
                _fs,
                _populate_priority,
            )

        # -- Mutex / Semaphore pairing ---------------------------------------
        if trace.has_sync_object_instrumentation:
            empty_sync = ("No mutex/sem activity in cursor range" if scope
                          else "No mutex/sem STI events in trace")

            def _populate_sync(blay: QVBoxLayout) -> None:
                _sync_rows = _sync_object_stats_rows(trace, lo, hi)
                _sync_issues_scoped = [
                    i for i in trace.sync_issues
                    if _sync_in_scope(i["time_ns"], lo, hi)
                ]
                host = QWidget()
                play = QVBoxLayout(host)
                play.setContentsMargins(0, 0, 0, 0)
                if not _sync_rows:
                    play.addWidget(self._lbl(empty_sync, color="#888888", ui_fs=_fs))
                else:
                    headers = ["Object", "Kind", "Holds", "Issues", "Bounces", "Avg hold", "Status"]
                    table = QTableWidget(len(_sync_rows), len(headers))
                    table.setHorizontalHeaderLabels(headers)
                    table.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)
                    table.setSelectionMode(QAbstractItemView.SelectionMode.NoSelection)
                    table.setFocusPolicy(Qt.FocusPolicy.NoFocus)
                    table.verticalHeader().setVisible(False)
                    table.horizontalHeader().setStretchLastSection(True)
                    table.setShowGrid(False)
                    table.setFrameShape(QFrame.NoFrame)
                    table.verticalHeader().setDefaultSectionSize(STATS_TABLE_ROW_H)
                    table.verticalHeader().setMinimumSectionSize(STATS_TABLE_ROW_H)
                    table.verticalHeader().setSectionResizeMode(QHeaderView.ResizeMode.Fixed)
                    table.horizontalHeader().setSectionsClickable(True)
                    table.horizontalHeader().setSortIndicatorShown(True)
                    self._apply_stats_table_theme(table, _fs)
                    _item_bg = QBrush(self._stats_table_colors()[0])
                    _status_rank = {"error": 0, "warning": 1, "ok": 2}
                    _sync_align = [
                        Qt.AlignmentFlag.AlignLeft, Qt.AlignmentFlag.AlignLeft,
                        Qt.AlignmentFlag.AlignRight, Qt.AlignmentFlag.AlignRight,
                        Qt.AlignmentFlag.AlignRight, Qt.AlignmentFlag.AlignRight,
                        Qt.AlignmentFlag.AlignLeft,
                    ]
                    for ri, row in enumerate(_sync_rows):
                        _key, kind, ptr, label, holds, issues, avg, status_label, status, avg_ns, bounces = row[:11]
                        vals = [label, kind, str(holds), str(issues), str(bounces), avg, status_label]
                        sort_keys = [
                            label.lower(), kind.lower(), holds, issues, bounces,
                            avg_ns if avg_ns is not None else -1,
                            _status_rank.get(status, 3),
                        ]
                        for ci, val in enumerate(vals):
                            item = _StatsSortItem(val, sort_keys[ci])
                            item.setFlags(Qt.ItemFlag.ItemIsEnabled)
                            item.setBackground(_item_bg)
                            item.setTextAlignment(_sync_align[ci] | Qt.AlignmentFlag.AlignVCenter)
                            if ci == 0:
                                item.setData(Qt.ItemDataRole.UserRole, _key)
                            if ci == 4 and bounces > 0:
                                item.setForeground(QBrush(QColor("#F39C12")))
                            if ci == 6 and status != "ok":
                                color = "#E74C3C" if status == "error" else "#F39C12"
                                item.setForeground(QBrush(QColor(color)))
                            table.setItem(ri, ci, item)
                    table.setSortingEnabled(True)
                    self._wire_stats_table_row_hover(table)
                    self._wrap_table_with_resizer(play, table, "sync")
                    _issues_display, _issues_cap_note = cap_stats_table_rows(
                        _sync_issues_scoped)
                    if _issues_display:
                        issue_headers = ["Object", "Time", "Detail", "Issue", "Task", "Core"]
                        itable = QTableWidget(len(_issues_display), len(issue_headers))
                        itable.setHorizontalHeaderLabels(issue_headers)
                        itable.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)
                        itable.setSelectionMode(QAbstractItemView.SelectionMode.NoSelection)
                        itable.setFocusPolicy(Qt.FocusPolicy.NoFocus)
                        itable.verticalHeader().setVisible(False)
                        itable.horizontalHeader().setStretchLastSection(True)
                        itable.setShowGrid(False)
                        itable.setFrameShape(QFrame.NoFrame)
                        itable.verticalHeader().setDefaultSectionSize(STATS_TABLE_ROW_H)
                        itable.verticalHeader().setMinimumSectionSize(STATS_TABLE_ROW_H)
                        itable.verticalHeader().setSectionResizeMode(QHeaderView.ResizeMode.Fixed)
                        itable.horizontalHeader().setSectionsClickable(True)
                        itable.horizontalHeader().setSortIndicatorShown(True)
                        self._apply_stats_table_theme(itable, _fs)
                        _item_bg = QBrush(self._stats_table_colors()[0])
                        _issue_align = [
                            Qt.AlignmentFlag.AlignLeft, Qt.AlignmentFlag.AlignRight,
                            Qt.AlignmentFlag.AlignLeft, Qt.AlignmentFlag.AlignLeft,
                            Qt.AlignmentFlag.AlignLeft, Qt.AlignmentFlag.AlignLeft,
                        ]

                        def _on_issue_row(row: int, _col: int) -> None:
                            item = itable.item(row, 0)
                            if item is None:
                                return
                            iss = item.data(Qt.ItemDataRole.UserRole)
                            if iss is None:
                                return
                            payload = SyncIssueRef(
                                time_ns=iss["time_ns"],
                                core=iss.get("core") or "",
                                kind=iss.get("kind", ""),
                                detail=iss.get("detail", ""),
                                obj_key=iss.get("obj_key"),
                                ptr=iss.get("ptr", ""),
                            )
                            self.plot_point_clicked.emit(
                                payload, iss["time_ns"], _format_sync_issue_note(iss))

                        itable.cellClicked.connect(_on_issue_row)
                        self._wire_stats_table_click_cursor(itable)
                        self._wire_stats_table_row_hover(itable)
                        for ri, iss in enumerate(_issues_display):
                            vals = [
                                iss.get("obj_key") or "—",
                                _format_time(iss["time_ns"], trace.time_scale),
                                iss.get("detail", ""),
                                iss.get("kind", ""),
                                iss.get("task_label") or "—",
                                iss.get("core") or "",
                            ]
                            sort_keys = [
                                (iss.get("obj_key") or "").lower(),
                                iss["time_ns"],
                                (iss.get("detail") or "").lower(),
                                (iss.get("kind") or "").lower(),
                                (iss.get("task_label") or "").lower(),
                                (iss.get("core") or "").lower(),
                            ]
                            tip = (f"Jump, zoom, and annotate at "
                                   f"{_format_time(iss['time_ns'], trace.time_scale)}")
                            for ci, val in enumerate(vals):
                                item = _StatsSortItem(val, sort_keys[ci])
                                item.setFlags(Qt.ItemFlag.ItemIsEnabled)
                                item.setBackground(_item_bg)
                                item.setTextAlignment(_issue_align[ci] | Qt.AlignmentFlag.AlignVCenter)
                                item.setToolTip(tip)
                                if ci == 0:
                                    item.setData(Qt.ItemDataRole.UserRole, iss)
                                if ci == 3:
                                    sev = iss.get("severity", "")
                                    if sev == "error":
                                        item.setForeground(QBrush(QColor("#E74C3C")))
                                    elif sev == "warning":
                                        item.setForeground(QBrush(QColor("#F39C12")))
                                itable.setItem(ri, ci, item)
                        itable.setSortingEnabled(True)
                        self._wrap_table_with_resizer(play, itable, "sync_issues")
                        self._add_stats_table_cap_note(play, _issues_cap_note, _fs)
                blay.addWidget(host)

            self._add_collapsible_section(
                "sync",
                f"Mutex / Semaphore{scope}",
                _fs,
                _populate_sync,
            )

