    cpu_splitter_bottom_h: Optional[int] = None
    font_size: int = 0
    ui_font_size: int = 0
    max_cursors: int = 0
    label_width: int = 0
    row_height: int = 0
    row_gap: int = 0
    sti_row_h: int = 0
    sti_waveform_h: int = 0
    sti_line_style: str = ""
    timescale_per_px_default: float = 0.0
    hover_highlight: bool = False
    cpu_load_row_h: int = 0
