                tb_pressed    = "#1C5A9E",
                tb_checked_bg = "#0E4D80",
                tb_checked_fg = "#FFFFFF",
                tb_disabled   = "#555555",
                status_text   = "#AAAAAA",
                cb_border     = "#555555",
                cb_bg         = "#2D2D2D",
                input_bg      = "#2D2D2D",
                input_fg      = "#D4D4D4",
                input_border  = "#555555",
                combo_bg      = "#2D2D2D",
                combo_view_bg = "#2D2D2D",
                dock_title_bg = "#2D2D2D",
                dock_title_fg = "#AAAAAA",
                list_hover    = "#3A3A3A",
