# ===========================================================================
# Entry point
# ===========================================================================

_XCB_CURSOR_SONAME = "libxcb-cursor.so.0"

def _find_xcb_cursor_lib() -> str:
    """Return a loadable path/soname for libxcb-cursor.so.0, or "" if absent.

    Search order (broadest first):
      1. ldconfig cache  — ctypes.util.find_library()
      2. LD_LIBRARY_PATH dirs — explicit file-existence scan
      3. Dynamic linker trial — ctypes.CDLL() (catches RPATH / other tricks)
    """
    import ctypes.util

    SONAME = _XCB_CURSOR_SONAME

    # 1. ldconfig cache
    if ctypes.util.find_library("xcb-cursor"):
        return SONAME

    # 2. LD_LIBRARY_PATH explicit scan — returns full path so caller can use it
    for d in os.environ.get("LD_LIBRARY_PATH", "").split(":"):
        if not d:
            continue
        candidate = os.path.join(d, SONAME)
        if os.path.isfile(candidate):
            return candidate

    # 3. Dynamic-linker trial (last resort)
    import ctypes
    try:
        lib = ctypes.CDLL(SONAME)
        return lib._name or SONAME
    except OSError:
        pass

    return ""

def _platform_preflight() -> None:
    """Ensure libxcb-cursor.so.0 is available before QApplication loads the
    xcb platform plugin.

    The xcb plugin (Qt ≥ 6.5) requires libxcb-cursor at link time.  When the
    library lives outside the ldconfig cache (e.g. in $HOME/.local/lib via
    LD_LIBRARY_PATH) Qt's internal dlopen() may still fail even though the
    dynamic linker can find it — because Qt's plugin loader sometimes runs
    before the process environment is fully propagated to glibc's dl cache.

    Solution: pre-load the library into the process with RTLD_GLOBAL *before*
    QApplication() is called.  This puts all xcb-cursor symbols into the
    global namespace so the xcb plugin can resolve them unconditionally.

    This function is a no-op on non-Linux platforms; xcb is a Linux-only Qt
    platform plugin and libxcb-cursor does not exist on Windows or macOS.
    """
    if sys.platform != "linux":
        return
    if os.environ.get("QT_QPA_PLATFORM", "xcb") != "xcb":
        return

    lib_path = _find_xcb_cursor_lib()

    if lib_path:
        import ctypes
        # Pre-load with RTLD_GLOBAL: symbols become visible to every subsequent
        # dlopen() in this process, including Qt's xcb platform plugin loader.
        load_path = lib_path if os.sep in lib_path else _XCB_CURSOR_SONAME
        try:
            ctypes.CDLL(load_path, mode=ctypes.RTLD_GLOBAL)
        except OSError:
            # Already loaded or path changed — try the bare soname as fallback
            try:
                ctypes.CDLL(_XCB_CURSOR_SONAME, mode=ctypes.RTLD_GLOBAL)
            except OSError:
                pass
        # Also keep LD_LIBRARY_PATH consistent so child processes benefit too
        if os.sep in lib_path:
            lib_dir = os.path.dirname(os.path.abspath(lib_path))
            parts = [p for p in os.environ.get("LD_LIBRARY_PATH", "").split(":") if p]
            if lib_dir not in parts:
                os.environ["LD_LIBRARY_PATH"] = ":".join([lib_dir] + parts)
        return

    print(
        "WARNING: The Qt xcb platform plugin requires libxcb-cursor0,\n"
        "  which was not found on this system.\n"
        "  Fix options:\n"
        "    1) Install the missing library:\n"
        "         sudo apt install libxcb-cursor0        # Debian / Ubuntu\n"
        "         sudo dnf install xcb-util-cursor       # Fedora / RHEL\n"
        "         sudo pacman -S xcb-util-cursor         # Arch\n"
        "    2) Copy libxcb-cursor.so.0 to a local dir and launch with:\n"
        "         LD_LIBRARY_PATH=/path/to/dir python btf_viewer.py\n"
        "    3) Use an alternative platform plugin:\n"
        "         QT_QPA_PLATFORM=offscreen python btf_viewer.py",
        file=sys.stderr,
    )

def _is_wsl() -> bool:
    if os.environ.get("WSL_DISTRO_NAME"):
        return True
    try:
        with open("/proc/version", "r", encoding="utf-8", errors="ignore") as f:
            return "microsoft" in f.read().lower()
    except OSError:
        return False

def _windows_applied_dpi() -> int | None:
    """Return the Windows user DPI (e.g. 144 @ 150 %, 192 @ 200 %) from WSL."""
    if not _is_wsl() or not shutil.which("powershell.exe"):
        return None
    try:
        out = subprocess.check_output(
            [
                "powershell.exe", "-NoProfile", "-Command",
                "(Get-ItemProperty 'HKCU:\\Control Panel\\Desktop\\WindowMetrics' "
                "-ErrorAction SilentlyContinue).AppliedDPI",
            ],
            text=True,
            stderr=subprocess.DEVNULL,
            timeout=5,
        ).strip()
        dpi = int(out)
    except (OSError, subprocess.SubprocessError, ValueError):
        return None
    return dpi if dpi >= 96 else None

def _wsl_wayland_force_dpi(applied: int) -> int:
    """Partial DPI nudge for WSLg — wl_output scale already reflects Windows zoom.

    Using the full Windows AppliedDPI doubles up with native DPR (UI too large).
    Apply only ~25 % of the gap above 96 DPI (120 @ 200 %, 108 @ 150 %).
    """
    if applied <= 96:
        return 96
    return 96 + (applied - 96) // 4

def _configure_wsl_wayland_dpi() -> None:
    """WSLg + Qt Wayland: slight DPI nudge when UI renders too small.

    WSLg exposes wl_output scale matching Windows zoom, but Qt Wayland clients
    can still look undersized. Do not re-apply the full Windows DPI — that
    doubles with native scale. Override with QT_WAYLAND_FORCE_DPI; disable
    auto-tuning with BTF_WSL_DPI=0.
    """
    if not _is_wsl() or sys.platform != "linux":
        return
    if os.environ.get("BTF_WSL_DPI", "1").strip().lower() in ("0", "false", "no", "off"):
        return
    plat = os.environ.get("QT_QPA_PLATFORM", "wayland").strip().lower()
    if plat not in ("", "wayland", "wayland-egl", "wayland-brcm"):
        return
    if os.environ.get("QT_WAYLAND_FORCE_DPI"):
        return
    applied = _windows_applied_dpi()
    if applied:
        os.environ["QT_WAYLAND_FORCE_DPI"] = str(_wsl_wayland_force_dpi(applied))

_HEADLESS_QPA_PLATFORMS = ("offscreen", "minimal", "vnc")

# Subcommands that render without a window server. Kept in sync with
# cli._CLI_COMMANDS by tests.
_HEADLESS_CLI_COMMANDS = frozenset({
    "report", "compare", "analyze", "ai-test", "info", "migrations", "snapshot",
    "perfetto", "slice",
})

def _headless_cli_invocation(argv: list[str] | None = None) -> bool:
    args = (sys.argv if argv is None else argv)[1:]
    return bool(args) and args[0] in _HEADLESS_CLI_COMMANDS

def _configure_qt_startup(argv: list[str] | None = None) -> None:
    # QT_FONT_DPI=96 was a PyQt5 workaround. Qt6 applies per-monitor DPI scaling
    # natively; forcing 96 DPI makes application fonts too small on Windows HiDPI.
    if sys.platform in ("win32", "linux"):
        os.environ.pop("QT_FONT_DPI", None)

    _configure_wsl_wayland_dpi()

    # A QT_QPA_PLATFORM=offscreen leaked from a CI/IDE shell would start the
    # macOS GUI with no visible window, so drop it there. CLI subcommands render
    # headless on purpose and must keep it: the cocoa plugin aborts inside
    # _RegisterApplication when LaunchServices is unreachable (sandbox, SSH).
    if sys.platform == "darwin" and not _headless_cli_invocation(argv):
        plat = os.environ.get("QT_QPA_PLATFORM", "").strip().lower()
        if plat in _HEADLESS_QPA_PLATFORMS:
            del os.environ["QT_QPA_PLATFORM"]
            print(
                f"warning: ignoring QT_QPA_PLATFORM={plat} so the window can be"
                " shown; use a CLI subcommand for headless rendering",
                file=sys.stderr,
            )

def _bootstrap_qt_app(argv: list[str] | None = None) -> QApplication:
    """Create or return QApplication with viewer font/bootstrap applied."""
    _configure_qt_startup()
    app = QApplication.instance()
    if app is None:
        app = QApplication(argv if argv is not None else [])
    app.setFont(_application_ui_font(UI_FONT_SIZE))
    return app

# ===========================================================================
# Entry point
# ===========================================================================

def _cli_ai_rc_cfg() -> Dict[str, str]:
    """Load ``[ai]`` from ``btf_viewer.rc``, decrypting ``*_api_key`` values."""
    rc = _RcSettings()
    cfg: Dict[str, str] = {}
    if hasattr(rc, "_cfg") and rc._cfg.has_section("ai"):
        for key in rc._cfg.options("ai"):
            cfg[key] = rc.get("ai", key)
    return cfg


def _cli_validate_range_pair(lo: Optional[int], hi: Optional[int], label: str) -> Optional[str]:
    if (lo is None) ^ (hi is None):
        return f"error: {label} requires both endpoints (e.g. --{label}-lo and --{label}-hi)"
    if lo is not None and hi is not None and hi <= lo:
        return f"error: {label} end must be greater than start"
    return None

def _cli_load_trace(path: str) -> Tuple[Optional["BtfTrace"], Optional[str]]:
    """Load a .btf path, including ``archive.zip::member.btf`` zip members."""
    load_path = _normalize_open_path(path)
    zip_path, _member = _split_zip_member_path(load_path)
    if not os.path.isfile(zip_path):
        return None, f"error: trace file not found: {zip_path}"
    try:
        return _parse_btf(load_path), None
    except Exception as exc:
        return None, f"error: failed to parse {load_path}: {exc}"


def _cli_compare_pair_members(members: List[str]) -> Optional[List[str]]:
    """Pick exactly two ``.btf`` zip members for Trace Compare.

    Prefers two top-level members when present (ignores nested duplicates);
    otherwise requires the archive to contain exactly two ``.btf`` files.
    """
    if len(members) == 2:
        return list(members)
    top = [n for n in members if "/" not in n and "\\" not in n]
    if len(top) == 2:
        return top
    return None


def _cli_resolve_compare_traces(
    traces: List[str],
) -> Tuple[Optional[str], Optional[str], Optional[str]]:
    """Resolve compare inputs to two load paths.

    Accepts either two ``.btf`` / ``zip::member`` paths, or one ``.zip`` that
    contains exactly two ``.btf`` members (or exactly two at the archive root).
    """
    if len(traces) == 2:
        return (
            _normalize_open_path(traces[0]),
            _normalize_open_path(traces[1]),
            None,
        )
    if len(traces) != 1:
        return None, None, (
            "error: compare expects two .btf paths, or one .zip with two .btf members"
        )

    path = _normalize_open_path(traces[0])
    zip_path, member = _split_zip_member_path(path)
    if member:
        return None, None, (
            "error: a single zip::member path is not enough; "
            "pass two members (a.zip::a.btf a.zip::b.btf) or the zip alone"
        )
    if not os.path.isfile(zip_path):
        return None, None, f"error: trace file not found: {zip_path}"

    if _sniff_compression(zip_path) != "zip":
        return None, None, (
            "error: compare needs two traces; pass a second .btf or a .zip "
            "with two .btf members"
        )

    try:
        with zipfile.ZipFile(zip_path, "r") as zf:
            names = zf.namelist()
            members = _list_zip_btf_members(names)
    except (OSError, zipfile.BadZipFile) as exc:
        return None, None, f"error: failed to read zip: {exc}"

    if not members:
        return None, None, f"error: {_zip_no_btf_message(names)}"

    picked = _cli_compare_pair_members(members)
    if picked is None:
        listing = ", ".join(members[:12])
        more = "…" if len(members) > 12 else ""
        return None, None, (
            f"error: zip has {len(members)} .btf members "
            f"(need exactly two, or exactly two at the archive root); "
            f"found: {listing}{more}. "
            f"Pass two paths as archive.zip::member.btf …"
        )
    return (
        f"{zip_path}{_ZIP_MEMBER_SEP}{picked[0]}",
        f"{zip_path}{_ZIP_MEMBER_SEP}{picked[1]}",
        None,
    )

def _cli_dual_ranges(args: argparse.Namespace) -> Tuple[Optional[int], Optional[int],
                                                        Optional[int], Optional[int],
                                                        Optional[str]]:
    """Resolve compare scope: shared --lo/--hi or per-trace --lo-a/--hi-a/--lo-b/--hi-b."""
    shared = args.lo is not None or args.hi is not None
    per_a = args.lo_a is not None or args.hi_a is not None
    per_b = args.lo_b is not None or args.hi_b is not None
    if shared and (per_a or per_b):
        return None, None, None, None, (
            "error: use either --lo/--hi (both traces) or --lo-a/--hi-a / --lo-b/--hi-b")
    if shared:
        err = _cli_validate_range_pair(args.lo, args.hi, "range")
        if err:
            return None, None, None, None, err
        return args.lo, args.hi, args.lo, args.hi, None
    err = _cli_validate_range_pair(args.lo_a, args.hi_a, "lo-a/hi-a")
    if err:
        return None, None, None, None, err
    err = _cli_validate_range_pair(args.lo_b, args.hi_b, "lo-b/hi-b")
    if err:
        return None, None, None, None, err
    return args.lo_a, args.hi_a, args.lo_b, args.hi_b, None

def _trace_info_payload(trace: "BtfTrace", path: str,
                        lo: Optional[int], hi: Optional[int]) -> dict:
    snap = _trace_summary_snapshot(trace, lo, hi)
    tick = _tick_health_report(trace, lo, hi)
    scale = trace.time_scale
    span_ns = snap["span_ns"]
    return {
        "file": path,
        "meta": dict(trace.meta),
        "time_scale": scale,
        "time_min": trace.time_min,
        "time_max": trace.time_max,
        "span_ns": span_ns,
        "span": _format_time(span_ns, scale),
        "cores": list(trace.core_names),
        "multi_core": _trace_is_multi_core(trace),
        "scope": {"lo": lo, "hi": hi} if lo is not None and hi is not None else None,
        "summary": {
            "tasks": snap["tasks"],
            "segments": snap["segments"],
            "sti_events": snap["sti_events"],
            "context_switches": snap["context_switches"],
            "core_gap_avg": _format_time(snap["gap_avg_ns"], scale),
            "core_gap_max": _format_time(snap["gap_max_ns"], scale),
            "migrations": snap["migrations"],
            "migrated_tasks": snap["migrated_tasks"],
        },
        "instrumentation": {
            "priority": trace.has_priority_instrumentation,
            "sync_objects": trace.has_sync_object_instrumentation,
            "intervals": bool(trace.interval_ids),
            "tags": bool(trace.tag_channels),
        },
        "tick_health": tick,
    }

def _build_migrations_csv(trace: "BtfTrace",
                          lo: Optional[int] = None,
                          hi: Optional[int] = None) -> str:
    header = ("Task,Migrations,Migr rate,Avg dwell,Core count,Primary core,"
              "Primary %,Ping-pong,STI near,Avg gap after,Avg gap other")
    lines = [header]
    for row in _migration_rows(trace, lo, hi):
        (_mk, name, n_mig, n_cores, _cores, primary, pct, ping, sti,
         ga, go, migr_rate, _rps, avg_dwell, _adtu) = row
        lines.append(",".join(_compare_csv_cell(c) for c in (
            name, n_mig, migr_rate, avg_dwell, n_cores, primary,
            f"{pct:.1f}", ping, sti, ga, go,
        )))
    return "\n".join(lines) + "\n"

